head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS15100.xml';
scwin.vMktactCd = '309'; //채권시장조치구분코드	
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId, scwin.gProcsStat = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.btnStat = new Object();
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.received_std_cd = ""; // 타화면에서 이 화면 오픈 시 건넨 표준코드
scwin.received_procs_tp = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 타화면에서 이 화면 오픈 시 건넨 처리현황(A:미신고,B:대용납입확인필요,C:신고완료,D:접수완료,E:처리완료)

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    $c.cm.setColumnProp(grd_List2, "CHK", "headcheck", false);
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 1) {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var std_cd = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
    var bnd_appl_id = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    var dsNm = 'BNS_FRN_ISU_CHG_INFO';
    var qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoCPnRtFrn';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_BND_APPL_ID=' + bnd_appl_id;
    param += '&{P}V_STD_CD=' + std_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명    : fn_SelectBdchrgList
 * 설명       : 신고담당자 목록 조회
 ***********************************************/
scwin.fn_SelectBdchrgList = function() {
    if (dts_List.getRowPosition() < 1) return;
    var isur_cd = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_BdchrgList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert("[적용일]을 입력하십시오.");
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    if ($c.stf.getObjectValue(edt_AfchgCpnIntRt) == '') {
        $c.win.alert("[변경후 이자율]을 입력하십시오.");
        edt_AfchgCpnIntRt.focus();
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_MinusGumriOK
 * JACKAL_191129
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_MinusGumriOK = function(obj, msg) {
    var obj_rt = $c.stf.getObjectValue(obj);
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            //setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};




/********************************************** 
* 함수명   : fn_MinusGumriCheck
* JACKAL_191129
* 설명       : 개별 체크한다.
edt_AfchgCpnIntRt AFCHG_COUPN_INT_RT
***********************************************/
scwin.fn_MinusGumriCheck = function() {
    if (!scwin.fn_MinusGumriOK(edt_AfchgCpnIntRt, '변경후 표면이자율') &&
        !scwin.fn_MinusGumriOK(edt_NxtrdBasInt, '낙찰금리')) return 1;

    else return 0;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return 1;
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //적용일,매매일,마감일,채권마감 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;
    var param1 = '';
    param1 += "&{P}V_STD_CD=" + scwin.vIsuCd; //

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readBndIsuInfo';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param1);
    var msg1 = "";
    var vSameYn = 'Y';
    var j = 1;
    var orgBasIntCd = dts_IsuInfo.getCellData(1, "INT_RT_DECSN_MISC_BAS_INT_CD");
    //var frnBasIntNm = getObjectText(cmb_IntRtDecsnMiscBasIntCd);
    var orgBasIntNm = "";
    //for (j = 1; j <= dts_CoupntRtCd.CountRow; j++) 
    //{
    //	if ( orgBasIntCd == dts_CoupntRtCd.NameValue(j, "VALUE") )
    //	{
    //	//strCbd = dts_CoupntRtCd.NameValue(j, "VALUE") + "^" + dts_CoupntRtCd.NameValue(j, "TEXT");
    //	orgBasIntNm = dts_CoupntRtCd.NameValue(j, "TEXT");
    //	}
    //}
    //if ( dts_DtlInfo.NameValue(1, "COUPN_RT_DECSN_BAS_INT_CD") != dts_IsuInfo.NameValue(1, "INT_RT_DECSN_MISC_BAS_INT_CD") )
    //{
    //	msg1 += " [기준금리] ";
    //	msg1 += "\n";
    //	//msg1 += " [상장채권정보]=[" + dts_IsuInfo.NameValue(1, "INT_RT_DECSN_MISC_BAS_INT_CD") + "] [변동금리정보]=" + dts_DtlInfo.NameValue(1, "COUPN_RT_DECSN_BAS_INT_CD") + "]";
    //	msg1 += " [상장채권]=[" + orgBasIntNm + "]";
    //	msg1 += "\n";
    //	msg1 += " [변동금리]=[" + frnBasIntNm + "]";
    //	msg1 += "\n";
    //	vSameYn = 'N';
    //}	
    if (dts_DtlInfo.getCellData(1, "SPD") != dts_IsuInfo.getCellData(1, "SPD")) {
        msg1 += " [가산금리] ";
        msg1 += "\n";
        msg1 += " [상장채권]=[" + dts_IsuInfo.getCellData(1, "SPD") + "]";
        msg1 += "\n";
        msg1 += " [변동금리]=[" + dts_DtlInfo.getCellData(1, "SPD") + "]";
        msg1 += "\n";
        vSameYn = 'N';
    }
    if (dts_DtlInfo.getCellData(1, "SPD_SGN") != dts_IsuInfo.getCellData(1, "SPD_SGN")) {
        msg1 += " [가산금리부호] ";
        msg1 += "\n";
        msg1 += " [상장채권]=[" + dts_IsuInfo.getCellData(1, "SPD_SGN") + "]";
        msg1 += "\n";
        msg1 += " [변동금리]=[" + dts_DtlInfo.getCellData(1, "SPD_SGN") + "]";
        msg1 += "\n";
        vSameYn = 'N';
    }
    if (vSameYn == 'N') {
        var msg2 = "기준금리항목 및 가산금리값이 상장채권정보와 다릅니다.";
        msg2 += "\n";
        msg2 += msg1;
        msg2 += "\n";
        msg2 += "발행기관에 확인 후 필요 시 종목정보를 수정하시기 바랍니다.";
        msg2 += "\n그래도 작업을 계속하시겠습니까?";
        if (!window.confirm(msg2)) return 1;
    }
    // 기준금리와 가산금리의 합이 변경후 표면이자율과 비교
    var vAfchgCoupnIntRt = parseFloat(dts_DtlInfo.getCellData(1, "AFCHG_COUPN_INT_RT"));
    var vSpdSgn = dts_DtlInfo.getCellData(1, "SPD_SGN");
    var vSpd = parseFloat(dts_DtlInfo.getCellData(1, "SPD"));
    var vNxtpdBasInt = parseFloat(dts_DtlInfo.getCellData(1, "NXTPD_BAS_INT"));
    if (vSpdSgn == '-') vSpd = -vSpd;

    // 값이 없는 경우 0 으로 셋팅
    if (dts_DtlInfo.getCellData(1, "AFCHG_COUPN_INT_RT") == '') {
        vAfchgCoupnIntRt = 0;
    }
    if (dts_DtlInfo.getCellData(1, "SPD") == '') {
        vSpd = 0;
    }
    if (dts_DtlInfo.getCellData(1, "NXTPD_BAS_INT") == '') {
        vNxtpdBasInt = 0;
    }
    if (Number(vAfchgCoupnIntRt.toFixed(6)) != Number((vSpd + vNxtpdBasInt).toFixed(6))) {
        var msg1 = "" + "기준금리와 가산금리의 합이 변경후 표면이자율과 다릅니다." + "\n" + "\n그래도 작업을 계속하시겠습니까?";
        if (!window.confirm(msg1)) return 1;
    }

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //첨부문서 체크
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;
    var url = "/bns/IsuChgEtc.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&REG_YN=" + 'N';
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    // 마이너스 금리 체크 (처리완료 및 수정만 체크토록 수정)
    if (!scwin.fn_MinusGumriCheck()) return 1; // JACKAL_191129

    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        url = "/bns/IsuChgEtc.do?method=updateAcpt";
    } else {
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;
        url = "/bns/IsuChgEtc.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 첨부파일 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 상장신청시 첨부 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKeyForList = function(arrPar) {
    arrPar[0] = {
        //상장신청시 첨부문서 목록 팝업
        //BND_APPL_ID						: dts_DtlInfo.NameValue(1, "BND_APPL_ID_FOR_LIST")	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "INT_RT_DECSN_MISC_BAS_INT_NM"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (scwin.gProcsStat == "처리완료") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        scwin.btnStat.Proc = "dis";
    } else {
        btn_Proc.src = "../img/bns/btn_20.gif";
        scwin.btnStat.Proc = "en";
    }
};



/********************************************** 
 * 함수명  	 : fn_ChgTab_Act
 * 설명       : 필드 ReadOnly 속성 제거/부여
 ***********************************************/
scwin.fn_ChgTab_Act = function(vBndListProcsTpCd) {
    //변경후 이자율, 사유발생일
    if (scwin.vBndListProcsTpCd == 1) {
        edt_AfchgCpnIntRt.setReadOnly(true);
        edt_IntRtDecsnBasDd.setReadOnly(true);
        //cmb_IntRtDecsnMiscBasIntCd.ReadOnly = true;
        //cmb_IntRtDecsnMiscBasIntCd.Enable2 = false;
        edt_NxtrdBasInt.setReadOnly(true);
        //txb_IntRtDecsnMiscBasIntNm.disabled = true;
        edt_AfchgCpnIntRt.setReadOnly(true);
        edt_IntPayDd.setReadOnly(true);
        cmb_SpdSgn.setDisabled(true);
        cmb_SpdSgn.setReadOnly(true);
        edt_Spd.setReadOnly(true);

        //달력가리기
        $c.stf.showObj(img_BasDd, false);
        $c.stf.showObj(img_PayDd, false);

