/********************************************** 
 * 함수명   : fn_setCheckBoxALL
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.fn_setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        //if (dtsObj.NameString(i, "PROCS_STAT") != '처리완료') { //처리완료만 팀장확인 대상임
        if (dtsObj.getCellData(i, "PROCS_STAT") != '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '')) {
            //처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};


/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};
scwin.fn_CompareRt = function() {
    var aftRt = dts_DtlInfo.getCellData(1, "AFCHG_COUPN_INT_RT"); // 변경후 표면이자율
    var aftBasInt = dts_DtlInfo.getCellData(1, "NXTPD_BAS_INT"); // 변경후 기준금리
    var aftSpd = dts_DtlInfo.getCellData(1, "SPD_SGN") + dts_DtlInfo.getCellData(1, "SPD"); // 변경후 기준금리

    var kscRt = dts_DtlInfo.getCellData(1, "KSC_FACE_INT"); // 코스콤 표면이자율
    var kscBasInt = dts_DtlInfo.getCellData(1, "KSC_BAS_INT"); // 코스콤 기준금리
    var kscSpd = dts_DtlInfo.getCellData(1, "KSC_SPD"); // 코스콤 가산금리

    if (Number(kscSpd) > 0) {
        kscSpd = "+" + kscSpd;
    }
    var different1 = false;
    var different2 = false;
    var different3 = false;

    // #15549c : readonly 기본 글자색
    // #343434 : 일반적인 글자색
    // #FF0000 : 빨간색
    // 코스콤 표면이자율과 변경후 표면이자율을 비교.. 다르면 색깔 표시
    if (kscRt != "" && kscRt != aftRt) {
        different1 = true;
        if (edt_AfchgCpnIntRt.ReadOnly) {
            edt_AfchgCpnIntRt.readonlyforecolor = "#FF0000";
        } else {
            edt_AfchgCpnIntRt.style.color = "#FF0000";
        }
    } else {
        different1 = false;
        if (edt_AfchgCpnIntRt.ReadOnly) {
            edt_AfchgCpnIntRt.readonlyforecolor = "#15549c";
        } else {
            edt_AfchgCpnIntRt.style.color = "#343434";
        }
    }

    // 기준금리 비교
    if (kscBasInt != "" && kscBasInt != aftBasInt) {
        different2 = true;
        if (edt_NxtrdBasInt.ReadOnly) {
            edt_NxtrdBasInt.readonlyforecolor = "#FF0000";
        } else {
            edt_NxtrdBasInt.style.color = "#FF0000";
        }
    } else {
        different2 = false;
        if (edt_NxtrdBasInt.ReadOnly) {
            edt_NxtrdBasInt.readonlyforecolor = "#15549c";
        } else {
            edt_NxtrdBasInt.style.color = "#343434";
        }
    }

    // 가산금리 비교
    if (kscSpd != "" && kscSpd != aftSpd) {
        different3 = true;
        if (edt_Spd.ReadOnly) {
            edt_Spd.readonlyforecolor = "#FF0000";
            //cmb_SpdSgn.style.color = "#FF0000";

        } else {
            edt_Spd.style.color = "#FF0000";
        }
    } else {
        different3 = false;
        if (edt_Spd.ReadOnly) {
            edt_Spd.readonlyforecolor = "#15549c";
        } else {
            edt_Spd.style.color = "#343434";
        }
    }
    if (different1 || different2 || different3) {
        $c.win.alert("상장법인이 제출한 FRN 변동금리 신청내역과 코스콤 데이터값이 상이합니다.\n확인 후 처리 바랍니다.");
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)

    $c.stf.showObj(btn_Excel, false);
    scwin.fn_SetComboCode();

    // 타화면에서 이 화면 오픈 시 건넨 값 저장
    scwin.received_std_cd = $c.stf.getQuery(frame.srcUrl, "STD_CD");
    scwin.received_procs_tp = $c.stf.getQuery(frame.srcUrl, "PROCS_TP"); // (A:미신고,B:대용납입확인필요,C:신고완료,D:접수완료,E:처리완료)

    // 접수완료, 처리완료 인 경우 tab2로 이동.
    if (scwin.received_procs_tp == "F" || scwin.received_procs_tp == "G") {
        tab_List.setSelectedTabIndex(2);
    } else {
        tab_List.setSelectedTabIndex(1);
    }
    scwin.vBndListProcsTpCd = tab_List.getSelectedTabIndex();

    //tab_List.ActiveIndex = 1;
    scwin.fn_list_sync(); //목록 조회

    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
    //필드 ReadOnly 속성 제거/부여
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    if (scwin.vBndListProcsTpCd == 2) {
        $c.stf.showObj(btn_Excel, true);
    } else {
        $c.stf.showObj(btn_Excel, false);
    }
    scwin.fn_list_sync(); //목록 조회
    //필드 ReadOnly 속성 제거/부여
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.CloseWin(rowcount, grd_List2);
        //접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
    } else {
        $c.cm.CloseWin(rowcount, grd_List1);
    }

    // 타화면에서 건네받은 표준코드가 존재하면 그 건을 선택
    if (scwin.received_std_cd != "") {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (scwin.received_std_cd == dts_List.getCellData(i, "STD_CD")) {
                dts_List.setRowPosition(i, 0);
                scwin.received_std_cd = ""; // 한번쓰고 초기화한다.
                scwin.received_procs_tp = "";
            }
        }
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.gBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        scwin.fn_dtl_sync();
        scwin.gProcsStat = dts_List.getCellData(row, "PROCS_STAT");
        scwin.fn_ProcBtnStat();
        scwin.fn_SelectBdchrgList();
    } else {
        dts_DtlInfo.removeAll();
        scwin.vDtlInfoRowCount = 0;
    }
};
