scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;

    // 코스콤 금리와 변경후 금리 비교..
    // [FRN금리변경] 신고화면 中 액셀첨부가 가능하도록 되어있는 주택금융공사에 한해 경고팝업이 접수, 처리완료, 팀장확인에서 뜨지 않도록 요청 25.02.17
    // 일괄신청 가능한 발행기관 모두 제외(중소기업은행(02411), 한국산업은행(04725), 한국주택금융공사(07915))
    var isur_cd = dts_DtlInfo.getCellData(1, "ISUR_CD");
    if (isur_cd != "02411" && isur_cd != "04725" && isur_cd != "07915") {
        scwin.fn_CompareRt();
    }
    edt_BfchgCpnIntRt.RightMargin = 5;
    edt_AfchgCpnIntRt.RightMargin = 5;
};
